insert into public.preguntas (id, recurso, modulo, texto, opciones, correcta, dato, usos) values
  ('q-j01', 'journals', 'Cuenta de administrador', 'Su biblioteca quiere saber cuánto se usa cada título para decidir renovaciones. ¿Dónde corre el administrador los reportes de uso?', '["Sage no ofrece reportes de uso","En el acceso de Administrador de la cuenta, con reportes COUNTER","Solo con las visitas al sitio web de la biblioteca","Pidiéndolos por correo cada trimestre"]'::jsonb, 1, 'El acceso de Administrador permite correr reportes COUNTER, ver la lista de entitlements, el Holdings Report, los rangos IP y los datos de Shibboleth u OpenAthens.', 0),
  ('q-j02', 'journals', 'Descubrimiento', 'Van a cargar la suscripción en su sistema de gestión de recursos electrónicos (ERM). ¿Qué les simplifica el trabajo?', '["Un CD con la lista de títulos","Feeds semanales para ERM compatibles con KBART II","Cargar cada título a mano","Un archivo que se envía una vez al año"]'::jsonb, 1, 'Hay feeds ERM semanales con el estándar KBART II y un solo paquete para todos los títulos Premier, indexado en Summon, Primo, EBSCO EDS y OCLC WorldShare.', 0),
  ('q-j03', 'journals', 'Acceso', 'Una egresada de su universidad quiere seguir leyendo revistas de Sage. ¿Qué dice Premier sobre los egresados?', '["Los egresados no tienen acceso","Los egresados registrados con la biblioteca suscriptora tienen acceso completo","Acceden pagando cada artículo","Solo pueden ver los resúmenes"]'::jsonb, 1, 'Premier incluye acceso completo para los egresados (alumni) registrados con las bibliotecas suscriptoras.', 0),
  ('q-j04', 'journals', 'Herramientas', 'Una investigadora quiere enterarse de los artículos nuevos de su tema sin buscar cada día. ¿Qué le recomiendan?', '["Revisar los índices impresos","Pedirle al bibliotecario que le avise","Descargar todo el contenido cada semana","Guardar sus búsquedas y revistas y crear alertas de contenido nuevo"]'::jsonb, 3, 'La plataforma permite guardar revistas y búsquedas y crear alertas de contenido nuevo, además de funciones para descubrir, navegar, leer y compartir.', 0),
  ('q-j05', 'journals', 'Cobertura', 'Un decano pregunta si Premier solo sirve a las ciencias sociales. ¿Qué responden?', '["Solo a educación y psicología","Cubre áreas interdisciplinarias: salud, negocios, ingeniería, artes y humanidades, educación y más","Solo a ciencias de la salud","Sí, únicamente a ciencias sociales"]'::jsonb, 1, 'Premier es interdisciplinario: va desde Arts & Humanities y Business & Management hasta Health Sciences, Engineering & Material Sciences y Science, Technology & Medicine.', 0),
  ('q-j06', 'journals', 'Acceso abierto', 'Quieren sumar también las revistas de acceso abierto Gold OA de Sage. ¿Qué deben recordar?', '["Ya vienen dentro de Premier","Se pagan artículo por artículo","No se pueden cargar en el ERM","Se ofrecen aparte, como paquete Sage Gold OA, y hay que cargarlo también en el ERM"]'::jsonb, 3, 'Gold OA es un paquete separado y los reportes de uso de Premier muestran solo el uso de títulos de pago. Si eligen paquetes, seleccionen Premier y todo Gold OA.', 0),
  ('q-j07', 'journals', 'Métricas', 'Un profesor va a publicar y quiere comparar el impacto de dos revistas de Sage. ¿Qué encuentra en las páginas de métricas de cada revista?', '["Solo el número de páginas por número","Únicamente el precio de la suscripción","Métricas de Journal Citation Reports, Scopus y Google Scholar, entre otras","Solo la lista de editores"]'::jsonb, 2, 'Cada revista tiene páginas de métricas (JCR, Scopus, Google Scholar) y cada artículo muestra su uso y sus citas de Crossref y Web of Science.', 0),
  ('q-j08', 'journals', 'Promoción y soporte', '¿Qué materiales ofrece Sage para que más estudiantes y docentes usen Premier?', '["Ninguno: la biblioteca debe crearlo todo","Únicamente descuentos en libros impresos","Solo un folleto impreso al año","Banners, widgets de búsqueda y pósteres, además de capacitaciones y guías"]'::jsonb, 3, 'Sage ofrece material de promoción (banners, widgets de búsqueda, pósteres), capacitaciones personalizadas, guías, videos y un equipo de soporte dedicado.', 0),
  ('q-j09', 'journals', 'Cobertura histórica', 'Un estudiante busca un artículo publicado en 2003. ¿Desde qué año ofrece Premier acceso a texto completo (donde esté disponible)?', '["Desde 1999","Solo desde 2015","Solo los últimos cinco años","Desde 1950"]'::jsonb, 0, 'Premier da acceso a más de 1,4 millones de artículos de texto completo desde 1999, donde está disponible. El Deep Backfile completa el archivo anterior.', 0),
  ('q-j10', 'journals', 'Sociedades académicas', 'Una vicerrectora pregunta por el respaldo académico de las revistas. ¿Qué parte de Premier se publica en nombre de sociedades?', '["Unos diez títulos","Ninguno: todas son propias de Sage","Más de 460 títulos de sociedades, como la American Sociological Association","Solo las de ciencias de la salud"]'::jsonb, 2, 'Premier incluye 466 títulos publicados en nombre de sociedades de prestigio, como la American Marketing Association, la American Sociological Association y la World Stroke Organization.', 0),
  ('q-j11', 'journals', 'Backfile', 'Quieren ser dueños del archivo histórico de revistas y ahorrar espacio de su colección impresa. ¿Qué opción les ofrece Sage?', '["No existe archivo anterior a 1999","Un USB que se renueva cada año","Comprar solo los números impresos","Deep Backfile: más de 680 revistas (más de 981.000 artículos) con propiedad del contenido"]'::jsonb, 3, 'El Deep Backfile llega hasta el volumen 1, número 1 de cada revista y ofrece propiedad del contenido con opciones flexibles de arriendo y compra.', 0),
  ('q-j12', 'journals', 'Acceso abierto', 'Una investigadora social busca una revista de acceso abierto de Sage. ¿Cuál fue la primera revista OA de amplio espectro en ciencias sociales y del comportamiento?', '["Sage Choice","Sage Campus","Sage Premier","Sage Open"]'::jsonb, 3, 'Sage lanzó Sage Open, la primera revista OA de amplio espectro en ciencias sociales y del comportamiento, y es miembro fundador de OASPA. Sage Choice es la opción híbrida para autores.', 0),
  ('q-b01', 'books', 'Obras de referencia', 'Un estudiante de primer semestre necesita entender rápido un concepto nuevo antes de leer artículos. ¿Qué contenido le sirve primero?', '["Una obra de referencia que explica conceptos con claridad","El artículo más reciente de su tema","Un informe estadístico sin explicación","Un conjunto de datos en bruto"]'::jsonb, 0, 'Las obras de referencia (enciclopedias, diccionarios, handbooks) son una puerta de entrada confiable a un tema, con contexto y bibliografía para seguir leyendo.', 0),
  ('q-b02', 'books', 'Libros académicos', 'Una docente arma su sílabo y busca un libro académico para toda la clase. ¿Qué conviene confirmar con la biblioteca?', '["El peso del libro impreso","El color de la portada","Nada: todos los libros funcionan igual","Cómo es el acceso: usuarios simultáneos, descarga y uso remoto"]'::jsonb, 3, 'Conocer el modelo de acceso evita sorpresas en clase: cuántas personas leen a la vez, qué se puede descargar y cómo se entra fuera del campus.', 0),
  ('q-b03', 'books', 'Obras de referencia', 'Una investigadora necesita un panorama de las escuelas teóricas de su campo antes de escribir su marco teórico. ¿Dónde empieza?', '["En redes sociales","En una base de datos de patentes","Solo en noticias recientes","En handbooks y obras de referencia que sintetizan el campo"]'::jsonb, 3, 'Los handbooks reúnen capítulos de especialistas que resumen el estado de un campo: un buen punto de partida para el marco teórico.', 0),
  ('q-b04', 'books', 'Valor para la institución', 'Si tuvieran que explicarle a su rectoría por qué los libros académicos complementan a las revistas, ¿qué argumento es más sólido?', '["Reemplazan por completo a las revistas","No se pueden medir ni usar a distancia","Solo sirven para decorar la biblioteca","Dan profundidad y contexto que un artículo no alcanza, y apoyan los cursos"]'::jsonb, 3, 'Los libros dan profundidad y contexto, apoyan los cursos y su uso se puede revisar con reportes.', 0),
  ('q-b05', 'books', 'Promoción', 'Quieren que más docentes descubran los libros electrónicos. ¿Qué acción suele funcionar mejor?', '["Imprimir la lista y pegarla en una cartelera","Retirarlos del catálogo","Integrarlos en el catálogo y compartir enlaces directos en el aula virtual","Esperar a que los encuentren solos"]'::jsonb, 2, 'Lo que está en el catálogo y en el aula virtual se usa más: el enlace directo lleva al libro justo en el momento en que se necesita.', 0),
  ('q-b06', 'books', 'Decisiones de compra', '¿Qué datos conviene mirar para decidir si siguen invirtiendo en libros electrónicos?', '["Solo la opinión de una persona","Uso por título, costo por uso y relación con los programas","Únicamente cuántos libros se compraron","Solo el color de la portada"]'::jsonb, 1, 'Combinen uso, costo y pertinencia: reportes por título y colección, costo por uso, relación con los programas y la voz de docentes y estudiantes.', 0),
  ('q-b07', 'books', 'Tipos de contenido', 'Un docente pregunta qué tipo de contenido encontrará en Reference & Academic Books. ¿Qué responden?', '["Solo videos de clases","Monografías, enciclopedias, diccionarios y handbooks","Solo artículos de revista","Únicamente conjuntos de datos"]'::jsonb, 1, 'Reúne textos académicos y obras de referencia (monografías, enciclopedias, diccionarios y handbooks), sobre todo en ciencias sociales y del comportamiento.', 0),
  ('q-b08', 'books', 'Uso en clase', 'Una estudiante solo necesita un capítulo de un handbook. ¿Qué puede hacer en la plataforma?', '["Nada: solo se puede leer el libro completo","Tomar una foto de la pantalla","Pedir el libro impreso por préstamo interbibliotecario","Buscar a nivel de capítulo o entrada y descargarlo en PDF"]'::jsonb, 3, 'Se puede buscar dentro de un título y a nivel de capítulo o entrada, y los capítulos y entradas de referencia se pueden descargar en PDF.', 0),
  ('q-b09', 'books', 'Descubrimiento', 'Un usuario termina un capítulo y quiere seguir explorando el tema. ¿Qué le ayuda en la plataforma?', '["Nada: debe volver a buscar desde cero","Un correo automático de la rectoría","Un listado impreso en la biblioteca","Sage Recommends, que sugiere contenido relacionado de Sage"]'::jsonb, 3, 'Sage Recommends sugiere contenido relacionado en distintos productos de Sage para que el usuario siga explorando.', 0),
  ('q-b10', 'books', 'Citación', 'Un estudiante necesita citar un capítulo en su trabajo. ¿Qué le ofrece la plataforma?', '["Solo copiar el título a mano","Citas únicamente en un formato propio","Guardar y descargar la cita en los principales formatos","Ninguna ayuda para citar"]'::jsonb, 2, 'La plataforma permite guardar y descargar citas en los principales formatos bibliográficos.', 0),
  ('q-b11', 'books', 'Cobertura temática', 'Un vicerrector académico pregunta cuál es el foco de la colección. ¿Qué responden?', '["Solo ingeniería civil","Solo derecho tributario","Es una biblioteca digital de ciencias sociales y del comportamiento","Únicamente cocina y turismo"]'::jsonb, 2, 'Reference & Academic Books es una biblioteca digital con fortaleza en ciencias sociales y del comportamiento: psicología, sociología, educación, enfermería y trabajo social, entre otras.', 0),
  ('q-b12', 'books', 'Currículo', 'Una coordinadora de programa quiere libros que respalden los cursos vigentes. ¿Qué característica de la colección le ayuda?', '["Solo trae libros de otro siglo","No tiene relación con ningún programa","Los títulos se seleccionan para alinearse con los cursos actuales","Los títulos se eligen al azar cada día"]'::jsonb, 2, 'Los títulos están seleccionados para alinearse con los cursos actuales y apoyar la docencia.', 0),
  ('q-s01', 'srm', 'Datasets', 'Un docente de métodos quiere que sus estudiantes practiquen análisis con datos reales sin tener que recolectarlos. ¿Qué módulo usan?', '["Datasets (conjuntos de datos)","Cases (casos)","Video","Methods Map"]'::jsonb, 0, 'Datasets trae datos descargables de fuentes gubernamentales y académicas, con guías paso a paso para análisis cuantitativo y cualitativo.', 0),
  ('q-s02', 'srm', 'Cases', 'Una doctoranda quiere ver cómo otros investigadores enfrentaron imprevistos reales en un proyecto parecido al suyo. ¿Qué módulo le conviene?', '["Project Planner","Datasets (conjuntos de datos)","Cases (casos)","Methods Map"]'::jsonb, 2, 'Los casos los escriben los propios investigadores: cuentan por qué eligieron sus métodos y cómo resolvieron lo que casi nunca aparece en un artículo.', 0),
  ('q-s03', 'srm', 'Project Planner', 'Una estudiante no sabe por dónde empezar su proyecto de investigación. ¿Qué herramienta la guía paso a paso?', '["Datasets","Cases","Project Planner","Methods Map"]'::jsonb, 2, 'Project Planner acompaña todo el proceso con consejos breves, lecturas sugeridas y listas de verificación prácticas.', 0),
  ('q-s04', 'srm', 'Methods Map', 'Quieren explorar qué conceptos y métodos se relacionan con la entrevista en profundidad. ¿Qué herramienta visual usan?', '["Datasets","Cases","Methods Map","Project Planner"]'::jsonb, 2, 'Methods Map es una visualización que conecta conceptos y métodos relacionados, para descubrir qué leer después.', 0),
  ('q-s05', 'srm', 'Books & Reference', 'Un estudiante de ciencias sociales necesita una introducción breve y rigurosa a una técnica estadística concreta. ¿Qué serie le conviene?', '["Datasets","Quantitative Applications in the Social Sciences (los \"Little Green Books\")","Methods Map","Cases"]'::jsonb, 1, 'En Books & Reference hay acceso completo a la serie Quantitative Applications in the Social Sciences, conocida como Little Green Books.', 0),
  ('q-s06', 'srm', 'Cases', 'Una profesora quiere llevar un caso al aula. ¿Qué trae cada caso para adaptarlo a su curso?', '["Objetivos de aprendizaje y preguntas de discusión","Un video obligatorio","Solo el archivo en PDF","Un examen calificado automáticamente"]'::jsonb, 0, 'Los casos incluyen objetivos de aprendizaje y preguntas de discusión, así que es fácil adaptarlos a un curso.', 0),
  ('q-s07', 'srm', 'Datasets', 'Un docente de estadística pierde horas buscando y limpiando datos para sus clases. ¿Cómo le ayuda Datasets?', '["Datos ya elegidos, con guías para SPSS, R, Stata y Python, y búsqueda por método, disciplina o formato","Solo ofrece datos para un único software","Solo entrega gráficos terminados","Le pide crear los datos desde cero"]'::jsonb, 0, 'Datasets ahorra la búsqueda y la limpieza: datos descargables con guías de software (SPSS, R, Stata y Python) y ejemplos con variables faltantes para aprender a manejar "datos sucios".', 0),
  ('q-s08', 'srm', 'Cases + Datasets', 'Van a diseñar una clase de 90 minutos sobre análisis de datos. ¿Cómo combinan Cases y Datasets?', '["Ven un video sin practicar nada","Abren con un caso para ver decisiones reales y practican el análisis con un dataset y su guía","Usan solo el dataset, sin ningún contexto","Leen únicamente un libro de referencia"]'::jsonb, 1, 'El caso muestra el porqué de los métodos y el dataset deja practicar el cómo: juntos cubren la decisión y la ejecución.', 0),
  ('q-s09', 'srm', 'Foundations', 'Una estudiante se topa con términos de investigación que no conoce, como diseño mixto o muestreo. ¿Qué módulo le da introducciones concisas?', '["Project Planner","Foundations, con cientos de entradas de referencia sobre métodos y conceptos","Video","Datasets"]'::jsonb, 1, 'Foundations reúne cientos de entradas de referencia sobre métodos cualitativos, cuantitativos y mixtos, con navegación que sugiere temas relacionados.', 0),
  ('q-s10', 'srm', 'Video', 'Un profesor quiere mostrar dos minutos de un video en clase y dejarlo en el aula virtual. ¿Qué ofrece la plataforma?', '["Los videos no se pueden incrustar","Solo videos de una hora, sin cortar","Solo se ven en un computador de la biblioteca","Clips personalizados y código para incrustarlo en el aula virtual"]'::jsonb, 3, 'Las herramientas de clips personalizados y los códigos para incrustar llevan el video justo al aula virtual; además hay transcripciones y subtítulos.', 0),
  ('q-s11', 'srm', 'Multimedia Collections', 'Una docente quiere un paquete temático (por ejemplo, Data Visualization o Doing Research Online) con videos, guías, casos y datos. ¿Qué módulo usa?', '["Multimedia Collections","Foundations","Project Planner","Methods Map"]'::jsonb, 0, 'Las Multimedia Collections son colecciones temáticas que mezclan videos, guías, casos y datasets, y se actualizan cada año.', 0),
  ('q-s12', 'srm', 'Books & Reference', 'Books & Reference es la piedra angular de Research Methods. ¿Cuántos títulos tiene, aproximadamente?', '["Unos 50 títulos","Unos 200 títulos","Menos de 20 títulos","Más de 1.000 títulos"]'::jsonb, 3, 'Books & Reference tiene más de 1.000 títulos que cubren todo el proceso de investigación y cientos de métodos, desde introducciones breves hasta explicaciones para expertos.', 0);
